import hashlib
from collections import defaultdict

skills_dir = "/home/bob/.hermes/skills"
skill_files = defaultdict(list)

# Find all SKILL.md files
for root, dirs, files in os.walk(skills_dir):
    for file in files:
        if file == "SKILL.md":
            full_path = os.path.join(root, file)
            skill_files[full_path].append(full_path)

# Check for duplicates by content
content_hashes = defaultdict(list)
duplicates = []

for skill_path in skill_files.keys():
    try:
        with open(skill_path, 'r', encoding='utf-8') as f:
            content = f.read()
            content_hash = hashlib.md5(content.encode()).hexdigest()
            content_hashes[content_hash].append(skill_path)
    except Exception as e:
        print(f"Error reading {skill_path}: {e}")

for hash_val, paths in content_hashes.items():
    if len(paths) > 1:
        duplicates.extend(paths)

print(f"Total SKILL.md files found: {len(skill_files)}")
print(f"Duplicate SKILL.md files (by content): {len(duplicates)}")
if duplicates:
    print("Duplicate files:")
    for dup in duplicates[:10]:  # Show first 10
        print(f"  {dup}")
    if len(duplicates) > 10:
        print(f"  ... and {len(duplicates) - 10} more")
else:
    print("No duplicate SKILL.md files found.")"}
